{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "isActive",
      "type": "boolean",
      "description": "Whether the tour is running. When false nothing renders and the tour resets to the first step, so it restarts cleanly next time it becomes active.",
      "required": true
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "The tour steps: TourStep elements. Step order follows their order here; only the active step renders its callout.",
      "slotElements": [
        {
          "__element": "TourStep",
          "props": {
            "heading": "Step"
          },
          "children": "Step body"
        }
      ]
    },
    {
      "name": "onDismiss",
      "type": "(source: TourDismissSource) => void",
      "description": "Called on every exit, with the reason ('backdrop' | 'escape' | 'close' | 'skip' | 'complete'). The consumer flips isActive to false in response, and can branch on the source to distinguish a successful finish from an early exit.",
      "required": true
    },
    {
      "name": "hasBackdrop",
      "type": "boolean",
      "description": "Dim the page around the active step as a spotlight cutout: the target stays lit while everything else darkens. Use for modal-style steps that demand focus; leave off for a lightweight coachmark that only rings the target.",
      "default": "false"
    },
    {
      "name": "isStepCountShown",
      "type": "boolean",
      "description": "Show the step count (\"2 of 5\") in each step.",
      "default": "false"
    },
    {
      "name": "targetRef",
      "type": "RefObject<HTMLElement>",
      "description": "Ref to the element this step points at. The callout anchors to it like a Popover trigger; it must be a <button> or [role=\"button\"] element (Popover's anchorRef contract).",
      "required": true
    },
    {
      "name": "heading",
      "type": "ReactNode",
      "description": "Step heading.",
      "required": true
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Step body content."
    },
    {
      "name": "placement",
      "type": "'above' | 'below' | 'start' | 'end'",
      "description": "Which side of the target the callout sits on.",
      "default": "'below'"
    },
    {
      "name": "alignment",
      "type": "'start' | 'center' | 'end'",
      "description": "How the callout aligns along the placement side (e.g. with placement=\"below\": start left-aligns under the target, center centers, end right-aligns).",
      "default": "'start'"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
